import socket, sys, runpy, os, time, pathlib, faulthandler
original_connect = socket.socket.connect
original_bind = socket.socket.bind
listeners = []
def local_bind(self, address):
    result = original_bind(self, address)
    if self.family in (socket.AF_INET, socket.AF_INET6) and address[0] in ('127.0.0.1', '::1'):
        listeners.append(self)
    return result
socket.socket.bind = local_bind
def deny(self, address):
    if self.family in (socket.AF_INET, socket.AF_INET6):
        allowed = {s.getsockname()[:2] for s in listeners if s.fileno() >= 0}
        if tuple(address[:2]) not in allowed: raise AssertionError('unowned or external connection forbidden')
    return original_connect(self,address)
socket.socket.connect=deny
sys.argv=['pytest']+sys.argv[1:]
runpy.run_module('pytest',run_name='__main__')
